#include <map>
#include <string>

// Generic function illustrating the replacement pattern
template <class Cont>
bool replace_key (Cont& c, 
                  const typename Cont::key_type& old_key, 
                  const typename Cont::key_type& new_key)
{
    auto pos = c.find(old_key);
    if (pos != c.end()) {
        // 1. Insert new element using old value
        c.insert(typename Cont::value_type(new_key, pos->second));
        // 2. Remove old element
        c.erase(pos);
        return true;
    }
    return false;
}
